def roman_to_int(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if not s:
        return 0
    total = 0
    prev = 0
    for ch in reversed(s.upper()):
        val = values.get(ch)
        if val is None:
            raise ValueError(f"Invalid Roman numeral character: {ch!r}")
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    return total
```

