def top_words(text, n):
    if not text or n <= 0:
        return []
    counts = {}
    word = []
    for ch in text.lower():
        if 'a' <= ch <= 'z':
            word.append(ch)
        else:
            if word:
                w = ''.join(word)
                counts[w] = counts.get(w, 0) + 1
                word = []
    if word:
        w = ''.join(word)
        counts[w] = counts.get(w, 0) + 1
    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:n]
