def camel_to_snake(s):
    if not s:
        return ""
    result = []
    for i, ch in enumerate(s):
        if ch.isupper():
            if i > 0 and (not s[i - 1].isupper() or (i + 1 < len(s) and s[i + 1].islower())):
                result.append("_")
            result.append(ch.lower())
        else:
            result.append(ch)
    return "".join(result)
```

